SELECT COUNT(1)
FROM t_res_base
WHERE rbs_id = #{resumeId}
  AND rbs_user_id = #{userId}
  AND rbs_status = 1

SELECT COUNT(1)
FROM t_res_attachment
WHERE rsa_resume_id = #{resumeId}
  AND rsa_user_id = #{userId}
  AND rsa_status = 1

SELECT rsa_id, rsa_resume_id, rsa_file_name, rsa_file_size, rsa_content_type,
       rsa_created_at, rsa_file_path
FROM t_res_attachment
WHERE rsa_id = #{attachmentId}
  AND rsa_resume_id = #{resumeId}
  AND rsa_user_id = #{userId}
  AND rsa_status = 1

mapper.update:
UPDATE t_res_attachment
SET rsa_status = 0
WHERE rsa_id = #{attachmentId}
  AND rsa_resume_id = #{resumeId}
  AND rsa_user_id = #{userId}
  AND rsa_status = 1
